    private ProvisionalScoreLookup() { }
    public static BigDecimal individual(int slider,int value) {
        return individualForVersion(slider,value,VERSION);
    }
    private static BigDecimal tableIndividual(int slider,int value) {
        if(slider<0||slider>=VALUES.length)throw new IllegalArgumentException("Unknown scoring slider");
        int offset=value-MIN[slider];
        if(offset<0||offset%STEP[slider]!=0||offset/STEP[slider]>=VALUES[slider].length)throw new IllegalArgumentException("Invalid scoring position");
        return new BigDecimal(VALUES[slider][offset/STEP[slider]]);
    }
    public static BigDecimal individualForVersion(int slider,int value,String calculationVersion) {
        if(!VERSION.equals(calculationVersion)&&!INTERIM_VERSION.equals(calculationVersion)&&!PREVIOUS_VERSION.equals(calculationVersion))
            throw new IllegalArgumentException("Unknown scoring calculation; preserve the run");
        BigDecimal base=tableIndividual(slider,value);
        if(slider!=17||value<15)return base;
        if(VERSION.equals(calculationVersion))return new BigDecimal(ACTIVE_UPGRADE_SCROLLS_15_TO_60[value-15]);
        if(INTERIM_VERSION.equals(calculationVersion)&&value==60)return INTERIM_60_SCROLL_FACTOR;
        return base;
    }
    public static BigDecimal combined(int[] values) {
        return combinedForVersion(values, VERSION);
    }
    /** Exact historical calculation, selected by the run's frozen calculation version. */
    public static BigDecimal combinedForVersion(int[] values, String calculationVersion) {
        if(values==null||values.length!=VALUES.length)throw new IllegalArgumentException("Incomplete scoring configuration");
        BigDecimal result=BigDecimal.ONE;
        for(int i=0;i<values.length;i++)result=result.multiply(individualForVersion(i,values[i],calculationVersion));
        return result.stripTrailingZeros();
    }
    /** Round the final earned score once; preserve SPD's already-computed original score. */
    public static long adjusted(long original,BigDecimal multiplier) {
        if(original<0||multiplier.signum()<=0)throw new IllegalArgumentException("Invalid score");
        return multiplier.multiply(BigDecimal.valueOf(original)).setScale(0,RoundingMode.HALF_UP).longValueExact();
    }
    public static String format(BigDecimal multiplier) {
        if(multiplier.signum()<=0)throw new IllegalArgumentException("Invalid multiplier");
        if(multiplier.compareTo(new BigDecimal("10000"))>=0||multiplier.compareTo(new BigDecimal("0.0001"))<0)
            return multiplier.round(new MathContext(5,RoundingMode.HALF_UP)).stripTrailingZeros().toEngineeringString()+"×";
        return multiplier.setScale(4,RoundingMode.HALF_UP).toPlainString()+"×";
    }
